const DAY = 86400000;
let seed = 7;
const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647; // fixed seed: same demo data every time
const pick = (a) => a[Math.floor(rnd() * a.length)];

// [type, count, id prefix, statuses, names]
const SPEC = [
  ["Task", 38, "TSK", ["Create", "Active", "Review", "Complete"],
    ["Land demarcation", "Site survey", "Grid connectivity agreement", "Foundation design review", "Vendor onboarding", "Permit approval", "Cable routing plan", "Safety audit"]],
  ["Issue", 16, "ISS", ["Open", "In Progress", "Resolved", "Closed"],
    ["Drawing mismatch", "Supplier delay", "Access road blocked", "Missing approval", "Specification conflict", "Budget overrun"]],
  ["Milestone", 8, "MST", ["Create", "Active", "Complete"],
    ["Design freeze", "Contract signed", "Site handover", "Commissioning", "Go-live"]],
  ["Phase", 6, "PHS", ["Create", "Active", "Complete"],
    ["Planning", "Procurement", "Construction", "Testing", "Handover"]],
  ["Risk", 8, "RSK", ["Identified", "Mitigating", "Closed"],
    ["Monsoon delay", "Material price rise", "Regulatory change", "Key resource loss"]],
  ["Project", 6, "PRJ", ["Create", "Active", "Complete"],
    ["Macro Project", "Demo Project", "Grid Upgrade", "Substation Build"]],
  ["Document", 8, "DOC", ["In Work", "Frozen", "Released"],
    ["Technical specification", "Test report", "Meeting minutes", "Design basis"]],
];

function build() {
  const now = Date.now();
  const rows = [];
  SPEC.forEach(([type, count, prefix, statuses, names]) => {
    for (let i = 1; i <= count; i++) {
      const created = now - (1 + rnd() * 120) * DAY;
      const modified = now - rnd() ** 2 * (now - created); // skewed to recent
      const roles = [];
      if (rnd() < 0.55) roles.push("owner");
      if (rnd() < 0.4) roles.push("created");
      if (rnd() < 0.7 || !roles.length) roles.push("modified");
      rows.push({
        id: `${prefix}-${1000 + rows.length}`,
        title: `${pick(names)} ${i}`,
        name: `${prefix}-${1000 + rows.length}`,
        type,
        status: pick(statuses),
        owner: "", creator: "", modifier: "",
        created: new Date(created).toISOString(),
        modified: new Date(modified).toISOString(),
        roles,
      });
    }
  });
  return rows;
}

// same contract as activityApi.fetchActivity(period, onRows); rows arrive in small batches
export async function fetchMockActivity(period, onRows) {
  const since = period.days ? Date.now() - period.days * DAY : 0;
  const rows = build().filter((r) => new Date(r.modified).getTime() >= since);
  for (let i = 0; i < rows.length; i += 20) {
    await new Promise((res) => setTimeout(res, 180));
    onRows(rows.slice(i, i + 20));
  }
  return { total: rows.length, capped: false };
}