import http from "./httpClient.js";
import dashboardApi from "./dashboardApi.js";
import { useDashboardStore } from "@/store/dashboardStore.js";
import { rolesOf } from "@/utils/activityRules";
import { ACTIVITY_FIELDS as F, ACTIVITY_MAX_ITEMS, ACTIVITY_PAGE } from "@/utils/dashboardData";

const SEARCH = "/federated/search";
const LABEL_FIELDS = ["ds6w:label", "dcterms:title", "ds6w:identifier"];
const TYPE_FIELDS = ["ds6w:type", "ds6w:what/ds6w:type"];

const toArray = (v) => [].concat(v ?? []);
const first = (r, name) =>
  toArray((r.attributes || []).find((a) => a.name === name)?.value)[0] ?? "";
const firstOf = (r, names) => names.map((n) => String(first(r, n))).find(Boolean) || "";
const esc = (s) => String(s).replace(/"/g, '\\"');

// names the current user can appear under in the index
export function identityOf() {
  const u = useDashboardStore().getUser || {};
  const full = `${u.firstName || ""} ${u.lastName || ""}`.trim();
  return [...new Set([full, u.login].filter(Boolean))];
}

function buildQuery(ids, sinceIso) {
  const who = ids
    .flatMap((v) => Object.values(F).map((p) => `[${p}]:"${esc(v)}"`))
    .join(" OR ");
  return sinceIso ? `(${who}) AND [ds6w:modified]>="${sinceIso}"` : `(${who})`;
}

const toRow = (r, i, ids) => {
  const row = {
    id: first(r, "resourceid") || `${first(r, "ds6w:identifier")}-${i}`,
    title: firstOf(r, LABEL_FIELDS) || String(r.label || r.title || ""),
    name: String(first(r, "ds6w:identifier")),
    type: firstOf(r, TYPE_FIELDS) || "–",
    status: String(first(r, "ds6w:status")).split(".").pop() || "–",
    owner: String(first(r, F.owner)),
    creator: String(first(r, F.created)),
    modifier: String(first(r, F.modified)),
    created: first(r, "ds6w:created"),
    modified: first(r, "ds6w:modified"),
  };
  row.roles = rolesOf(row, ids);
  return row;
};

export default {
  // onRows(batch) is called after every page; returns { total, capped }
  async fetchActivity(period, onRows) {
    const ids = identityOf();
    if (!ids.length) throw new Error("NO_USER");

    const since = period.days ? new Date(Date.now() - period.days * 86400000).toISOString() : null;
    const query = buildQuery(ids, since);

    let next = null;
    let total = 0;
    for (let page = 0; page < 100; page++) {
      const p = dashboardApi.buildPayload("Task", {}, ACTIVITY_PAGE, next, query);
      p.query = query;
      p.refine = {}; // all object types
      p.source = ["3dspace"];
      p.select_predicate = [...new Set([...(p.select_predicate || []), "resourceid", ...TYPE_FIELDS])];
      if (!next) p.start = "0";

      const json = await http.post(SEARCH, p);
      const batch = (json.results || []).map((r, i) => toRow(r, total + i, ids));
      total += batch.length;
      onRows(batch);

      next = json.infos?.next_start;
      if (batch.length < ACTIVITY_PAGE || !next || total >= ACTIVITY_MAX_ITEMS) break;
    }
    return { total, capped: total >= ACTIVITY_MAX_ITEMS };
  },
};