<template>
  <v-dialog persistent :model-value="modelValue" max-width="460"
    @update:model-value="$emit('update:modelValue', $event)">
    <div class="dd-card">
      <div class="dd-head">
        <div class="dd-icon"><v-icon icon="mdi-star-circle-outline" size="22" /></div>
        <div>
          <div class="dd-title">Projects Monitoring</div>
          <!-- <div class="dd-sub">Find the projects a Sub Type is used in</div> -->
        </div>
      </div>

      <div class="dd-body">
        <v-select v-model="subType" :items="['Task', 'Issue', 'Phase', 'Milestone', 'Risk', 'Route']" variant="outlined"
          density="comfortable" hide-details>
          <template #label>Sub type <span class="dd-req">*</span></template>
        </v-select>

        <v-text-field v-model="name" placeholder="e.g. Field Testing" variant="outlined" density="comfortable"
          hide-details @keyup.enter="go">
          <template #label>Name <span class="dd-req">*</span></template>
        </v-text-field>

        <v-combobox v-model="status" :items="['Active', 'Create', 'Assign', 'Review', 'Complete']"
          label="Status (optional)" clearable hide-no-data variant="outlined" density="comfortable" hide-details />
      </div>
      <div class="dd-actions">
        <button class="dd-btn dd-cancel" @click="$emit('update:modelValue', false)">Cancel</button>
        <button class="dd-btn dd-go" :disabled="!name.trim() || loading" @click="go">
          {{ loading ? "Searching…" : "Show Dashboard" }}
        </button>
      </div>
    </div>
  </v-dialog>
</template>

<script>
export default {
  props: { modelValue: Boolean, loading: Boolean },
  emits: ["update:modelValue", "submit"],
  data: () => ({ subType: "Task", name: "", status: "" }),
  methods: {
    go() {
      if (this.name.trim() && !this.loading)
        this.$emit("submit", { subType: this.subType, name: this.name, status: this.status });
    },
  },
};
</script>

<style scoped>
.dd-card {
  background: #fff;
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.18);
}

.dd-head {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px 24px;
  border-bottom: 1px solid #eee;
}

.dd-icon {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: rgba(15, 98, 254, 0.08);
  color: #0f62fe;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
}

.dd-title {
  font-size: 17px;
  font-weight: 700;
  color: #1a1a1a;
}

.dd-sub {
  font-size: 13px;
  color: #666;
  margin-top: 2px;
}

.dd-body {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 22px 24px;
}

.dd-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 14px 24px;
  background: #fafafa;
  border-top: 1px solid #eee;
}

.dd-btn {
  height: 38px;
  padding: 0 20px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, box-shadow 0.15s, transform 0.1s;
}

.dd-cancel {
  background: #fff;
  color: #444;
  border: 1px solid #ccc;
}

.dd-cancel:hover {
  background: #f5f7fa;
  border-color: #999;
}

.dd-go {
  background: #0f62fe;
  color: #fff;
  border: 1px solid #0f62fe;
}

.dd-go:hover:not(:disabled) {
  background: #0a4fd1;
  box-shadow: 0 2px 8px rgba(15, 98, 254, 0.35);
}

.dd-go:disabled {
  background: #b9c9e8;
  border-color: #b9c9e8;
  cursor: not-allowed;
}

.dd-btn:active:not(:disabled) {
  transform: scale(0.97);
}

.dd-req {
  color: #da1e28;
  font-weight: 700;
}
</style>