<template>
  <div class="db-wrap">
    <div class="topbar">
      <div class="topbar-left">
        <button class="btn-outline" @click="$emit('go-home')">
          <v-icon icon="mdi-home-outline" size="14" /> {{ text.home }}
        </button>

        <span class="label">{{ text.period }}</span>
        <v-menu>
          <template #activator="{ props }">
            <div class="type-pill" v-bind="props" title="Change period">
              {{ period.label }} <v-icon icon="mdi-chevron-down" size="16" />
            </div>
          </template>
          <v-list density="compact">
            <v-list-item
              v-for="p in periods"
              :key="p.id"
              :title="p.label"
              :active="p.id === periodId"
              @click="periodId = p.id"
            />
          </v-list>
        </v-menu>

        <v-menu v-model="menu" :close-on-content-click="false" location="bottom start">
          <template #activator="{ props }">
            <div class="filter-pill" v-bind="props">{{ text.filters }} ({{ activeChips.length }})</div>
          </template>

          <div class="fp-card">
            <div class="fp-head"><v-icon icon="mdi-close" size="18" title="Close" @click="menu = false" /></div>

            <div class="fp-group">
              <div class="fp-label">{{ text.search }}</div>
              <v-text-field
                v-model="draft.search"
                density="compact"
                variant="outlined"
                hide-details
                :placeholder="text.searchHint"
              />
            </div>

            <div v-for="g in chipGroups" :key="g.key" class="fp-group">
              <div class="fp-label">{{ g.label }}</div>
              <div class="fp-chips">
                <span
                  v-for="o in g.options"
                  :key="o.value"
                  class="fp-chip"
                  :class="{ active: draft[g.key].includes(o.value) }"
                  @click="toggleDraft(g.key, o.value)"
                >{{ o.label }}</span>
              </div>
            </div>

            <div v-for="d in dateGroups" :key="d.key" class="fp-group">
              <div class="fp-label">{{ d.label }}</div>
              <div class="fp-chips mb-2">
                <span
                  v-for="p in presets"
                  :key="p.id"
                  class="fp-chip"
                  :class="{ active: isPreset(d, p) }"
                  @click="setPreset(d, p)"
                >{{ p.label }}</span>
              </div>
              <div class="fp-date-row">
                <input v-model="draft[d.from]" type="date" class="fp-date-input" />
                <span class="fp-date-sep">to</span>
                <input v-model="draft[d.to]" type="date" class="fp-date-input" />
              </div>
            </div>

            <button class="fp-btn" @click="applyDraft">{{ text.apply }}</button>
          </div>
        </v-menu>
      </div>

      <div class="topbar-right">
        <span v-if="loading" class="refreshed">{{ text.loaded }} {{ rows.length }}…</span>
        <span v-else class="refreshed">{{ text.refreshed }} {{ lastRefreshed }}</span>
        <v-icon icon="mdi-refresh" size="18" class="icon-btn" :class="{ spin: loading }" title="Refresh" @click="load" />
      </div>
    </div>

    <div v-if="activeChips.length" class="chips-row">
      <span v-for="c in activeChips" :key="c.id" class="chip">
        {{ c.label }}
        <v-icon icon="mdi-close" size="12" title="Remove filter" @click="c.remove()" />
      </span>
      <span class="clear-all" @click="clearAll">{{ text.clearAll }}</span>
    </div>

    <div class="content">
      <div class="main">
        <StateMessage v-if="loading && !rows.length" icon="mdi-loading" :title="text.loadingTitle" :message="text.loadingMessage" />
        <StateMessage
          v-else-if="error"
          icon="mdi-power-plug-off-outline"
          badge-color="#FDECEA"
          icon-color="#DC3545"
          :title="text.errorTitle"
          :message="error"
          :action-label="text.retry"
          @action="load"
        />
        <StateMessage v-else-if="!rows.length" icon="mdi-package-variant" badge-color="#F0F2F5" icon-color="#9E9E9E" :title="text.emptyTitle" :message="text.emptyMessage" />
        <StateMessage
          v-else-if="!filtered.length"
          icon="mdi-filter-off-outline"
          badge-color="#F0F2F5"
          icon-color="#9E9E9E"
          :title="text.noMatchTitle"
          :message="text.noMatchMessage"
          :action-label="text.clearAll"
          @action="clearAll"
        />

        <template v-else>
          <div v-if="capped" class="warn">
            <v-icon icon="mdi-alert-outline" size="16" /> {{ text.capped.replace("{n}", maxItems) }}
          </div>

                    <div class="tiles">
            <button
              v-for="k in kpis"
              :key="k.kind + k.val"
              class="tile"
              :class="{ on: drill && drill.kind === k.kind && drill.val === k.val }"
              :style="{ '--c': k.color }"
              :title="text.viewItems"
              @click="openDrill(k.kind, k.val, k.label, true)"
            >
              <span class="tile-icon"><v-icon :icon="k.icon" size="22" /></span>
              <span class="tile-body">
                <span class="tile-value">{{ k.value }}</span>
                <span class="tile-label">{{ k.label }}</span>
                <span class="tile-bar"><i :style="{ width: k.pct + '%' }" /></span>
                <span class="tile-sub">{{ k.pct }}% {{ text.of }} {{ summary.total }} {{ text.items.toLowerCase() }}</span>
              </span>
              <v-icon icon="mdi-chevron-right" size="18" class="tile-go" />
            </button>
          </div>

          <div class="panel-row">
            <div class="panel">
              <div class="panel-head"><div class="panel-title">{{ text.byType }}</div></div>
              <div class="donut-row">
                <div class="chart-container">
                  <apexchart type="donut" height="260" :options="donutOptions" :series="typeSeries" />
                </div>
                <div class="legend">
                  <div
                    v-for="(t, i) in chartSummary.byType"
                    :key="t[0]"
                    class="legend-row"
                    :class="{ dim: drill && drill.kind === 'type' && drill.val !== t[0] }"
                    @click="openDrill('type', t[0])"
                  >
                    <span class="dot" :style="{ background: palette[i % palette.length] }" />
                    <span class="legend-label">{{ t[0] }}</span>
                    <span class="legend-value">{{ t[1] }} ({{ pct(t[1], chartSummary.total) }}%)</span>
                  </div>
                </div>
              </div>
            </div>

            <div class="panel">
              <div class="panel-head"><div class="panel-title">{{ text.byStatus }}</div></div>
              <apexchart type="bar" height="260" :options="barOptions" :series="statusSeries" />
            </div>
          </div>

          <div class="panel-row">
            <div class="panel">
              <div class="panel-head"><div class="panel-title">{{ text.overTime }}</div></div>
              <apexchart v-if="line.labels.length" type="area" height="260" :options="areaOptions" :series="areaSeries" />
              <div v-else class="panel-empty">–</div>
            </div>

            <div class="panel">
              <div class="panel-head"><div class="panel-title">{{ text.byAge }}</div></div>
              <apexchart type="bar" height="260" :options="ageOptions" :series="ageSeries" />
            </div>
          </div>

          <div v-if="!useMock" class="foot">
            {{ text.matching }}: <b>{{ identity.join(", ") || "–" }}</b> {{ text.matchingHint }}
          </div>
        </template>
      </div>

      <ActivityDrillPanel v-if="drill" :label="drill.label" :rows="drillRows" @close="drill = null" />
    </div>
  </div>
</template>

<script>
import VueApexCharts from "vue3-apexcharts";
import ActivityDrillPanel from "@/components/dashboard/ActivityDrillPanel.vue";
import StateMessage from "@/components/common/StateMessage.vue";
import activityApi, { identityOf } from "@/services/activityApi";
import { fetchMockActivity } from "@/utils/activityMock";
import { applyFilters, summarize, timeline, ageBuckets } from "@/utils/activityRules";
import {
  ACTIVITY_USE_MOCK,
  ACTIVITY_PERIODS,
  DEFAULT_ACTIVITY_PERIOD,
  ACTIVITY_DATE_PRESETS,
  ACTIVITY_ROLES,
  ACTIVITY_LAST7,
  ACTIVITY_AGE_COLORS,
  ACTIVITY_MAX_ITEMS,
  COLORS,
  PALETTE,
} from "@/utils/dashboardData";
import { ACTIVITY_TEXT } from "@/utils/uiText";
import { toastBus } from "@/components/common/toastBus";

const DAY = 86400000;
const emptyFilters = () => ({
  search: "", type: [], status: [], role: [],
  createdFrom: "", createdTo: "", modifiedFrom: "", modifiedTo: "",
});
const cloneFilters = (f) => ({ ...f, type: [...f.type], status: [...f.status], role: [...f.role] });
const isoDaysAgo = (days) => {
  const d = new Date(Date.now() - days * DAY);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
};
const modTime = (r) => (r.modified ? new Date(r.modified).getTime() || 0 : 0);
const AGE_MAX = [7, 30, 90, Infinity]; // same bands as ageBuckets()
const ageIdx = (r) => AGE_MAX.findIndex((m) => (Date.now() - modTime(r)) / DAY <= m);
const GRID = { strokeDashArray: 4 };
const INT = { min: 0, forceNiceScale: true, labels: { formatter: (v) => Math.round(v) } };

export default {
  name: "MyActivityView",
  components: { apexchart: VueApexCharts, StateMessage, ActivityDrillPanel },
  emits: ["go-home"],
  data() {
    return {
      text: ACTIVITY_TEXT,
      useMock: ACTIVITY_USE_MOCK,
      periods: ACTIVITY_PERIODS,
      presets: ACTIVITY_DATE_PRESETS,
      roles: ACTIVITY_ROLES,
      palette: PALETTE,
      maxItems: ACTIVITY_MAX_ITEMS,
      dateGroups: [
        { key: "created", label: ACTIVITY_TEXT.created, from: "createdFrom", to: "createdTo" },
        { key: "modified", label: ACTIVITY_TEXT.modified, from: "modifiedFrom", to: "modifiedTo" },
      ],
      periodId: DEFAULT_ACTIVITY_PERIOD,
      filters: emptyFilters(),
      draft: emptyFilters(),
      menu: false,
      drill: null, // { kind: 'type'|'status'|'age', val, label }
      rows: [],
      loading: false,
      capped: false,
      error: "",
      lastRefreshed: "–",
      req: 0,
    };
  },
  computed: {
    identity: () => identityOf(),
    period() {
      return this.periods.find((p) => p.id === this.periodId);
    },
    roleById() {
      return Object.fromEntries(this.roles.map((r) => [r.id, r]));
    },
    typeOptions() {
      return [...new Set(this.rows.map((r) => r.type))].sort();
    },
    statusOptions() {
      return [...new Set(this.rows.map((r) => r.status))].sort();
    },
    chipGroups() {
      return [
        { key: "type", label: this.text.typeLabel, options: this.typeOptions.map((v) => ({ value: v, label: v })) },
        { key: "status", label: this.text.statusLabel, options: this.statusOptions.map((v) => ({ value: v, label: v })) },
        { key: "role", label: this.text.roleLabel, options: this.roles.map((r) => ({ value: r.id, label: r.label })) },
      ];
    },
    activeChips() {
      const f = this.filters;
      const out = [];
      if (f.search) out.push({ id: "search", label: `${this.text.search}: ${f.search}`, remove: () => (f.search = "") });
      ["type", "status", "role"].forEach((k) =>
        f[k].forEach((v) =>
          out.push({
            id: k + v,
            label: `${this.text[k + "Label"]}: ${k === "role" ? this.roleById[v].label : v}`,
            remove: () => (f[k] = f[k].filter((x) => x !== v)),
          }),
        ),
      );
      this.dateGroups.forEach((d) => {
        if (f[d.from] || f[d.to])
          out.push({
            id: d.key,
            label: `${d.label}: ${f[d.from] || "…"} → ${f[d.to] || "…"}`,
            remove: () => {
              f[d.from] = "";
              f[d.to] = "";
            },
          });
      });
      return out;
    },
    filtered() {
      return applyFilters(this.rows, this.filters);
    },
    // type / status charts ignore their own filter so every slice stays visible
    chartRows() {
      return applyFilters(this.rows, { ...this.filters, type: [], status: [] });
    },
    summary() {
      return summarize(this.filtered);
    },
    chartSummary() {
      return summarize(this.chartRows);
    },
    line() {
      return timeline(this.filtered);
    },
    ages() {
      return ageBuckets(this.filtered);
    },
    drillRows() {
      const d = this.drill;
      if (!d) return [];
      const base = [...(["type", "status"].includes(d.kind) ? this.chartRows : this.filtered)].sort(
        (a, b) => modTime(b) - modTime(a),
      );
      return base.filter((r) =>
        d.kind === "type" ? r.type === d.val
        : d.kind === "status" ? r.status === d.val
        : d.kind === "role" ? r.roles.includes(d.val)
        : ageIdx(r) === d.val, // "age" bucket or "recent" (bucket 0 = last 7 days)
      );
    },
    kpis() {
      const s = this.summary;
      const share = (n) => (s.total ? Math.round((n / s.total) * 100) : 0);
      return [
        ...this.roles.map((r) => ({ kind: "role", val: r.id, label: r.label, icon: r.icon, color: r.color, value: s[r.id], pct: share(s[r.id]) })),
        { kind: "recent", val: 0, ...ACTIVITY_LAST7, value: s.last7, pct: share(s.last7) },
      ];
    },
    typeSeries() {
      return this.chartSummary.byType.map((x) => x[1]);
    },
    statusSeries() {
      return [{ name: this.text.items, data: this.chartSummary.byStatus.map((x) => x[1]) }];
    },
    areaSeries() {
      return [
        { name: this.text.createdBy, data: this.line.created },
        { name: this.text.modifiedBy, data: this.line.modified },
      ];
    },
    ageSeries() {
      return [{ name: this.text.items, data: this.ages.map((x) => x[1]) }];
    },
    donutOptions() {
      const labels = this.chartSummary.byType.map((x) => x[0]);
      return {
        chart: {
          toolbar: { show: false },
          events: { dataPointSelection: (e, c, cfg) => this.openDrill("type", labels[cfg.dataPointIndex]) },
        },
        labels,
        colors: PALETTE,
        legend: { show: false },
        dataLabels: { enabled: false },
        stroke: { width: 0 },
        plotOptions: { pie: { donut: { size: "55%" } } },
      };
    },
    barOptions() {
      const cats = this.chartSummary.byStatus.map((x) => x[0]);
      return {
        chart: {
          toolbar: { show: false },
          events: { dataPointSelection: (e, c, cfg) => this.openDrill("status", cats[cfg.dataPointIndex]) },
        },
        plotOptions: { bar: { horizontal: true, borderRadius: 4, barHeight: "60%" } },
        colors: [COLORS.blue],
        xaxis: { categories: cats },
        dataLabels: { enabled: true },
        grid: GRID,
      };
    },
    areaOptions() {
      return {
        chart: { toolbar: { show: false } },
        colors: [COLORS.green, COLORS.purple],
        stroke: { curve: "smooth", width: 3 },
        markers: { size: 4, hover: { size: 6 } },
        dataLabels: { enabled: false },
        grid: GRID,
        xaxis: { categories: this.line.labels, tickAmount: Math.min(10, this.line.labels.length) },
        yaxis: INT,
        legend: { position: "top" },
      };
    },
    ageOptions() {
      return {
        chart: {
          toolbar: { show: false },
          events: {
            dataPointSelection: (e, c, cfg) =>
              this.openDrill("age", cfg.dataPointIndex, this.ages[cfg.dataPointIndex][0]),
          },
        },
        plotOptions: { bar: { distributed: true, borderRadius: 4, columnWidth: "45%" } },
        colors: ACTIVITY_AGE_COLORS,
        xaxis: { categories: this.ages.map((x) => x[0]) },
        yaxis: INT,
        legend: { show: false },
        dataLabels: { enabled: true },
        grid: GRID,
      };
    },
  },
  watch: {
    periodId() {
      this.load();
    },
    menu(open) {
      if (open) this.draft = cloneFilters(this.filters); // popup always starts from what is applied
    },
  },
  mounted() {
    this.load();
  },
  methods: {
    pct: (n, total) => (total ? Math.round((n / total) * 100) : 0),
   openDrill(kind, val, label = val, plain = false) {
      const name = { type: this.text.typeLabel, status: this.text.statusLabel, age: this.text.byAge }[kind];
      this.drill = { kind, val, label: plain || !name ? label : `${name}: ${label}` };
    },
    toggleDraft(key, val) {
      const a = this.draft[key];
      this.draft[key] = a.includes(val) ? a.filter((x) => x !== val) : [...a, val];
    },
    isPreset(d, p) {
      return p.days
        ? !this.draft[d.to] && this.draft[d.from] === isoDaysAgo(p.days)
        : !this.draft[d.from] && !this.draft[d.to];
    },
    setPreset(d, p) {
      this.draft[d.from] = p.days ? isoDaysAgo(p.days) : "";
      this.draft[d.to] = "";
    },
    applyDraft() {
      this.filters = cloneFilters(this.draft);
      this.menu = false;
    },
    clearAll() {
      this.filters = emptyFilters();
    },
    async load() {
      const id = ++this.req; // a newer load invalidates older ones
      this.rows = [];
      this.drill = null;
      this.capped = false;
      this.error = "";
      this.loading = true;
      try {
        const fetcher = this.useMock ? fetchMockActivity : (p, cb) => activityApi.fetchActivity(p, cb);
        const res = await fetcher(this.period, (batch) => {
          if (id === this.req) this.rows = [...this.rows, ...batch];
        });
        if (id === this.req) {
          this.capped = res.capped;
          this.lastRefreshed = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
        }
      } catch (e) {
        if (id === this.req) {
          this.error = e.message === "NO_USER" ? this.text.noUser : this.text.errorMessage;
          toastBus.emit(this.text.errorTitle, "error");
        }
      } finally {
        if (id === this.req) this.loading = false;
      }
    },
  },
};
</script>

<style scoped>
/* same values as DashboardView / KpiCards / ChartPanel / FilterPopup */
.db-wrap { padding: 16px 20px; box-sizing: border-box; }
.db-wrap button, .db-wrap select, .db-wrap input { font-family: inherit; }

.topbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; flex-wrap: wrap; gap: 8px; }
.topbar-left { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.topbar-right { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.label { font-size: 13px; color: #666; }
.type-pill { display: flex; align-items: center; gap: 2px; border: 1px solid #ddd; border-radius: 6px; padding: 4px 10px; font-size: 13px; color: #0f62fe; background: #fff; cursor: pointer; }
.filter-pill { font-size: 13px; color: #0f62fe; cursor: pointer; }
.refreshed { font-size: 12px; color: #888; }
.demo-pill { font-size: 11px; font-weight: 600; color: #8a5a00; background: #fff6e0; border: 1px solid #f1d38a; border-radius: 6px; padding: 2px 8px; }
.icon-btn { color: #666; cursor: pointer; }
.spin { animation: spin 0.9s linear infinite; }
@keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

.btn-outline { display: inline-flex; align-items: center; gap: 4px; color: #0f62fe; background: #fff; border: 1.5px solid #0f62fe; border-radius: 8px; padding: 6px 12px; font-size: 13px; font-weight: 600; cursor: pointer; transition: background 0.15s ease, transform 0.1s ease; }
.btn-outline:hover { background: rgba(15, 98, 254, 0.08); }
.btn-outline:active { transform: scale(0.97); }

.chips-row { display: flex; align-items: center; gap: 8px; overflow-x: auto; white-space: nowrap; margin-bottom: 16px; padding-bottom: 2px; }
.chip { display: inline-flex; align-items: center; gap: 4px; background: #e8f0fe; color: #0f62fe; font-size: 12px; padding: 4px 8px; border-radius: 6px; flex-shrink: 0; }
.chip .v-icon { cursor: pointer; }
.clear-all { font-size: 12px; color: #0f62fe; cursor: pointer; text-decoration: underline; flex-shrink: 0; }

.fp-card { width: 320px; max-width: 90vw; max-height: 70vh; overflow-y: auto; background: #fff; padding: 16px; }
.fp-head { display: flex; justify-content: flex-end; margin-bottom: 4px; }
.fp-head .v-icon { cursor: pointer; }
.fp-group { margin-bottom: 16px; }
.fp-label { font-size: 13px; font-weight: 700; color: #1a1a1a; margin-bottom: 8px; }
.fp-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.fp-chip { border: 1px solid #ddd; border-radius: 20px; padding: 5px 12px; font-size: 12px; cursor: pointer; color: #444; }
.fp-chip.active { border-color: #0f62fe; color: #0f62fe; background: rgba(15, 98, 254, 0.08); font-weight: 600; }
.fp-date-row { display: flex; align-items: center; gap: 8px; }
.fp-date-input { flex: 1; min-width: 0; border: 1px solid #ddd; border-radius: 8px; padding: 7px 8px; font-size: 12px; color: #333; }
.fp-date-sep { font-size: 12px; color: #888; }
.fp-btn { width: 100%; margin-top: 4px; background: #0f62fe; color: #fff; border: none; border-radius: 8px; padding: 10px; font-size: 13px; font-weight: 600; cursor: pointer; }

.content { display: flex; gap: 16px; align-items: flex-start; height: calc(100vh - 85px); }
.main { flex: 1; min-width: 0; height: 100%; overflow-y: auto; overflow-x: hidden; padding-right: 8px; }
.main::-webkit-scrollbar { width: 8px; }
.main::-webkit-scrollbar-thumb { background: #c7c7c7; border-radius: 4px; }
.main::-webkit-scrollbar-thumb:hover { background: #999; }

.warn { display: flex; align-items: center; gap: 8px; margin-bottom: 14px; padding: 8px 14px; font-size: 13px; color: #8a5a00; background: #fff6e0; border: 1px solid #f1d38a; border-radius: 10px; }

.panel-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px; }
.panel { background: #fff; border: 1px solid #eee; border-radius: 10px; padding: 16px; min-width: 0; width: 100%; box-sizing: border-box; }
.panel-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.panel-title { font-size: 13px; font-weight: 600; color: #0f62fe; }
.panel-empty { height: 260px; display: flex; align-items: center; justify-content: center; color: #bbb; }

.donut-row { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.chart-container { flex: 1; min-width: 220px; }
.legend { flex: 1; min-width: 180px; }
.legend-row { display: flex; align-items: center; gap: 8px; padding: 6px 4px; border-radius: 6px; cursor: pointer; }
.legend-row:hover { background: #f5f7fa; }
